      unit: "ms",
      target: REQUIREMENTS.jitter.recommended,
      status: jitter <= REQUIREMENTS.jitter.recommended ? "pass" : jitter <= REQUIREMENTS.jitter.max ? "marginal" : "fail",
      detail: jitter <= REQUIREMENTS.jitter.recommended ? "Netcode'un bir sonraki paketini tahmin edebilmesi için yeterince kararlı." : jitter <= REQUIREMENTS.jitter.max ? `${REQUIREMENTS.jitter.recommended} ms hedefinin üzerinde. ${connection.label.toLowerCase()} için tipik, yönlendiricide düzeltilebilir.` : "Bu, çatışmaların haksız hissettirmesine neden olan sayıdır. Ham hız peşinde koşmadan önce bunu düzelt."
