  const verdict = !worst ? `Bağlantın ${region.label} için tüm hedefleri karşılıyor. Burada hiçbir şey GTA 6'yı geri tutmayacak.` : blocking ? `${worst.label} engeldir. Önce bunu düzelt, temizlenene kadar diğer sayılar pek önemli değil.` : `Her yerde oynanabilir, ${worst.label.toLowerCase()} rahat bandın hemen dışında.`;
